<?php
require __DIR__.'/../src/bootstrap.php';$user=require_admin();$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        post_guard();verify_current_password((int)$user['id'],input('admin_password'));
        $id=filter_var(input('user_id'),FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if(!$id)throw new FormError('Usuário inválido.');
        $action=input('action');
        transaction(function()use($id,$user,$action){
            $actor=query("SELECT id FROM users WHERE id=? AND role='admin' AND active=1",[$user['id']])->fetch();if(!$actor)throw new FormError('Seu acesso de administrador foi revogado.');
            $target=query('SELECT * FROM users WHERE id=?',[$id])->fetch();if(!$target)throw new FormError('Usuário não encontrado.');
            if($id===$user['id'])throw new FormError('Use Minha conta para gerenciar sua própria conta.');
            if(!in_array($action,['promote','demote','disable','enable','revoke'],true))throw new FormError('Ação inválida.');
            if(in_array($action,['demote','disable'],true) && $target['role']==='admin' && $target['active'] && (int)query("SELECT COUNT(*) FROM users WHERE role='admin' AND active=1")->fetchColumn()<=1) throw new FormError('Mantenha ao menos um administrador ativo.');
            if($action==='promote')query("UPDATE users SET role='admin' WHERE id=?",[$id]);
            if($action==='demote')query("UPDATE users SET role='user' WHERE id=?",[$id]);
            if($action==='disable')query('UPDATE users SET active=0 WHERE id=?',[$id]);
            if($action==='enable')query('UPDATE users SET active=1 WHERE id=?',[$id]);
            query('DELETE FROM sessions WHERE user_id=?',[$id]);audit((int)$user['id'],$action,$id);
        });redirect('/admin.php?saved=1');
    }catch(FormError $ex){$error=$ex->getMessage();}
}
$q=mb_substr(is_string($_GET['q']??null)?trim($_GET['q']):'',0,100);
$page=max(1,min(100000,(int)($_GET['page']??1)));$like='%'.$q.'%';
$total=(int)query('SELECT COUNT(*) FROM users WHERE name LIKE ? OR email LIKE ?',[$like,$like])->fetchColumn();$pages=max(1,(int)ceil($total/20));$page=min($page,$pages);
$users=query('SELECT id,name,email,role,active,created_at,last_login_at FROM users WHERE name LIKE ? OR email LIKE ? ORDER BY id DESC LIMIT 20 OFFSET '.(($page-1)*20),[$like,$like])->fetchAll();
$stats=query("SELECT COUNT(*) AS total,COALESCE(SUM(active),0) AS active,COALESCE(SUM(role='admin' AND active=1),0) AS admins FROM users")->fetch();
$logs=query('SELECT a.*,u.name AS actor_name,t.name AS target_name FROM audit_log a LEFT JOIN users u ON a.actor_id=u.id LEFT JOIN users t ON a.target_id=t.id ORDER BY a.id DESC LIMIT 12')->fetchAll();
$labels=['login'=>'Entrou na conta','logout'=>'Saiu da conta','cadastro'=>'Criou uma conta','primeiro_admin'=>'Configurou o administrador','perfil'=>'Atualizou o perfil','senha_alterada'=>'Alterou a própria senha','sessoes_encerradas'=>'Encerrou as próprias sessões','promote'=>'Promoveu a administrador','demote'=>'Alterou para torcedor','disable'=>'Bloqueou a conta','enable'=>'Reativou a conta','revoke'=>'Encerrou as sessões'];
require __DIR__.'/../src/layout.php';page_start('Administração',$user);
?>
<main class="account-main admin-main" id="conteudo"><div class="account-heading"><div><span class="eyebrow">PAINEL ADMINISTRATIVO</span><h1>ALMA ALVINEGRA.<br><em>SOB SEU CUIDADO.</em></h1></div><span class="role-badge">ACESSO RESTRITO</span></div><?php error_box($error); ?><?php if(isset($_GET['saved'])||isset($_GET['ready'])): ?><div class="form-message success" role="status"><?= isset($_GET['ready'])?'Administrador configurado. Seu painel está pronto.':'Acesso atualizado. As sessões anteriores desse usuário foram encerradas.' ?></div><?php endif; ?><div class="admin-stats"><div><strong><?= (int)$stats['total'] ?></strong><span>Contas cadastradas</span></div><div><strong><?= (int)$stats['active'] ?></strong><span>Contas ativas</span></div><div><strong><?= (int)$stats['admins'] ?></strong><span>Administradores ativos</span></div></div><section class="panel"><div class="panel-heading"><div><span class="eyebrow">01 / COMUNIDADE</span><h2>GERENCIAR CONTAS.</h2></div><form class="search-form" method="get"><label class="visually-hidden" for="q">Buscar por nome ou e-mail</label><input id="q" name="q" value="<?= e($q) ?>" placeholder="Nome ou e-mail" maxlength="100"><button class="button gold">Buscar</button></form></div><div class="users-list"><?php foreach($users as $member): ?><article class="user-row"><div class="user-info"><span class="avatar"><?= e(mb_strtoupper(mb_substr($member['name'],0,1))) ?></span><div><h3><?= e($member['name']) ?><?= $member['id']===$user['id']?' <small>(você)</small>':'' ?></h3><p><?= e($member['email']) ?></p><small>Último acesso: <?= e(format_date($member['last_login_at']===null?null:(int)$member['last_login_at'])) ?></small></div></div><div class="user-badges"><span class="role-badge"><?= $member['role']==='admin'?'Administrador':'Torcedor' ?></span><span class="status-badge <?= $member['active']?'':'blocked' ?>"><?= $member['active']?'Ativo':'Bloqueado' ?></span></div><?php if($member['id']!==$user['id']): ?><details class="user-actions"><summary>Gerenciar ↗</summary><form method="post"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$member['id'] ?>"><label for="action-<?= (int)$member['id'] ?>">O que deseja fazer?</label><select name="action" id="action-<?= (int)$member['id'] ?>"><option value="revoke">Encerrar sessões</option><option value="<?= $member['active']?'disable':'enable' ?>"><?= $member['active']?'Bloquear conta':'Reativar conta' ?></option><option value="<?= $member['role']==='admin'?'demote':'promote' ?>"><?= $member['role']==='admin'?'Alterar para torcedor':'Promover a administrador' ?></option></select><label for="confirm-<?= (int)$member['id'] ?>">Sua senha de administrador</label><input id="confirm-<?= (int)$member['id'] ?>" type="password" name="admin_password" autocomplete="current-password" required maxlength="72"><button class="button gold submit" data-confirm="Aplicar esta alteração e encerrar os acessos atuais dessa conta?">Confirmar alteração ↗</button></form></details><?php endif; ?></article><?php endforeach; ?><?php if(!$users): ?><p class="empty-state">Nenhuma conta encontrada para esta busca.</p><?php endif; ?></div><div class="pagination"><span><?= $total ?> conta<?= $total===1?'':'s' ?> · Página <?= $page ?> de <?= $pages ?></span><div><?php if($page>1): ?><a href="?<?= e(http_build_query(['q'=>$q,'page'=>$page-1])) ?>">← Anterior</a><?php endif; ?><?php if($page<$pages): ?><a href="?<?= e(http_build_query(['q'=>$q,'page'=>$page+1])) ?>">Próxima →</a><?php endif; ?></div></div></section><section class="panel audit-panel"><span class="eyebrow">02 / ATIVIDADE RECENTE</span><h2>REGISTRO DE ACESSOS.</h2><div class="audit-list"><?php foreach($logs as $log): ?><div><time><?= e(format_date((int)$log['created_at'])) ?></time><p><strong><?= e($log['actor_name']??'Sistema') ?></strong> · <?= e($labels[$log['action']]??$log['action']) ?><?php if($log['target_id']!==$log['actor_id']): ?> · <?= e($log['target_name']??'Conta') ?><?php endif; ?></p></div><?php endforeach; ?></div></section></main><?php page_end(); ?>
